import random, itertools, collections, time
n=19
edges_all=[(i,j) for i in range(n) for j in range(i+1,n)]

def dist(adj,s,t,limit=5):
    # return <=limit if found, else None / >limit
    if s==t: return 0
    seen={s}; q=collections.deque([(s,0)])
    while q:
        v,d=q.popleft()
        if d>=limit: continue
        for w in adj[v]:
            if w==t: return d+1
            if w not in seen:
                seen.add(w); q.append((w,d+1))
    return None

def greedy():
    adj=[set() for _ in range(n)]; edges=[]
    candidates=edges_all[:]
    while True:
        good=[]
        for e in candidates:
            u,v=e
            if v in adj[u]: continue
            d=dist(adj,u,v,5) # if path length <=5 then cycle <=6 forbidden
            if d is None:
                good.append(e)
        if not good: return edges, adj
        # random choose with bias maybe high degree? 
        e=random.choice(good)
        u,v=e; adj[u].add(v); adj[v].add(u); edges.append(e)
        candidates.remove(e)

def colorable3(edges):
    adj=[set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    order=sorted(range(n), key=lambda x: -len(adj[x]))
    colors=[-1]*n
    def dfs(k):
        if k==n: return colors[:]
        v=order[k]
        used={colors[w] for w in adj[v] if colors[w]>=0}
        for c in range(3):
            if c not in used:
                colors[v]=c
                r=dfs(k+1)
                if r: return r
                colors[v]=-1
        return None
    return dfs(0)

best=[]; bestcol=None
start=time.time()
for it in range(20000):
    e,adj=greedy()
    if len(e)>len(best):
        col=colorable3(e)
        best=e[:]; bestcol=col
        print('it',it,'edges',len(e),'3col',bool(col), 'deg', sorted([len(a) for a in adj]))
        if len(e)>=28 and col:
            print('FOUND',e,col); break
    if len(e)>=28:
        col=colorable3(e)
        if col:
            print('FOUND it',it,'m',len(e),e,col); break
else:
    print('best',len(best),best,bestcol)
print('time',time.time()-start)

